"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { useEffect, useId, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BehaviourStep, type Tone } from "./ai-setup-wizard/behaviour-step";
import {
  GUARDRAILS,
  MODELS,
  SOURCES,
  STEP_NAMES,
} from "./ai-setup-wizard/data";
import { SourceStep } from "./ai-setup-wizard/source-step";
import { Stepper } from "./ai-setup-wizard/stepper";
import { TestStep } from "./ai-setup-wizard/test-step";
import { BlockFrame } from "../parts/block-frame";

// Critically damped: the steps slide across and stop with no bounce.
const SLIDE: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 35,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

const INITIAL_PROGRESS = Object.fromEntries(
  SOURCES.map((source) => [source.id, source.start]),
);

/**
 * A three-step setup card for a front desk assistant: connect its sources,
 * choose how it behaves, then test it with a question. The steps slide inside
 * a fixed-height window, so the card never changes size.
 */
export function AiSetupWizard({ className }: { className?: string }) {
  const reduceMotion = useReducedMotion();
  const [step, setStep] = useState(0);
  const [progress, setProgress] = useState(INITIAL_PROGRESS);
  const [model, setModel] = useState(MODELS[1]!.id);
  const [tone, setTone] = useState<Tone>("warm");
  const [guards, setGuards] = useState(
    GUARDRAILS.filter((guard) => guard.on).map((guard) => guard.id),
  );
  const [live, setLive] = useState(false);
  const titleId = useId();

  const syncing = Object.values(progress).some(
    (value) => value !== null && value < 100,
  );

  // One interval moves every syncing source forward, and it stops once none is left.
  useEffect(() => {
    if (!syncing) return;
    const id = window.setInterval(() => {
      setProgress((current) =>
        Object.fromEntries(
          Object.entries(current).map(([key, value]) => [
            key,
            value !== null && value < 100 ? Math.min(100, value + 3) : value,
          ]),
        ),
      );
    }, 120);
    return () => window.clearInterval(id);
  }, [syncing]);

  const connect = (id: string) =>
    setProgress((current) => ({ ...current, [id]: reduceMotion ? 100 : 0 }));
  const guard = (id: string, on: boolean) =>
    setGuards((current) =>
      on ? [...current, id] : current.filter((item) => item !== id),
    );
  const connected = Object.values(progress).filter(
    (value) => value === 100,
  ).length;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-4 border-b border-border px-5 py-4">
        <div className="flex items-start justify-between gap-3">
          <div className="flex min-w-0 items-start gap-3">
            <span
              aria-hidden="true"
              className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-marketing-purple-surface text-marketing-purple-ink"
            >
              <SparklesIcon className="size-4" />
            </span>
            <div className="min-w-0">
              <h2 id={titleId} className="text-base font-semibold">
                Front desk assistant
              </h2>
              <p className="truncate text-sm text-muted-foreground">
                Answers patient questions for Harbour Street
              </p>
            </div>
          </div>
          <span
            role="status"
            className={cn(
              "shrink-0 rounded-full px-2.5 py-0.5 text-xs font-medium",
              live
                ? "bg-marketing-green-surface text-marketing-green-ink"
                : "bg-muted text-muted-foreground",
            )}
          >
            {live ? "Live" : "Draft"}
          </span>
        </div>
        <Stepper names={STEP_NAMES} step={step} onStep={setStep} />
      </header>

      <div className="relative h-108 overflow-hidden">
        <motion.div
          initial={false}
          animate={{ x: `${-step * 100}%` }}
          transition={reduceMotion ? INSTANT : SLIDE}
          className="flex h-full"
        >
          {[
            <SourceStep
              key="sources"
              progress={progress}
              onConnect={connect}
            />,
            <BehaviourStep
              key="behaviour"
              model={model}
              onModel={setModel}
              tone={tone}
              onTone={setTone}
              guards={guards}
              onGuard={guard}
            />,
            <TestStep key="test" />,
          ].map((panel, index) => (
            <section
              key={STEP_NAMES[index]}
              aria-label={STEP_NAMES[index]}
              inert={index !== step}
              className="scroll-fade-effect-y scrollbar-none h-full w-full shrink-0 overflow-y-auto px-5 py-4"
            >
              {panel}
            </section>
          ))}
        </motion.div>
      </div>

      <footer className="flex items-center justify-between gap-3 border-t border-border px-5 py-3">
        <p className="min-w-0 truncate text-xs text-muted-foreground">
          {step === 0
            ? `${connected} of ${SOURCES.length} sources ready`
            : step === 1
              ? `${MODELS.find((item) => item.id === model)?.name}, ${tone}, ${guards.length} guardrails`
              : live
                ? "Patients can now ask it questions"
                : "Test it, then publish"}
        </p>
        <div className="flex shrink-0 gap-2">
          <Button
            variant="outline"
            size="sm"
            disabled={step === 0}
            onClick={() => setStep(step - 1)}
          >
            Back
          </Button>
          {step < STEP_NAMES.length - 1 ? (
            <Button size="sm" onClick={() => setStep(step + 1)}>
              Continue
            </Button>
          ) : (
            <Button size="sm" disabled={live} onClick={() => setLive(true)}>
              {live ? "Published" : "Publish"}
            </Button>
          )}
        </div>
      </footer>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

