"use client";

import { useId } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Switch } from "@/components/motion/switch";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { ShieldIcon } from "../icons";
import { GUARDRAILS, MODELS, TONES } from "./data";

/** A tone the assistant writes in. */
export type Tone = (typeof TONES)[number]["value"];

/** Props for step two, the behaviour. */
export interface BehaviourStepProps {
  model: string;
  onModel: (id: string) => void;
  tone: Tone;
  onTone: (tone: Tone) => void;
  /** The ids of the guardrails that are on. */
  guards: string[];
  onGuard: (id: string, on: boolean) => void;
}

/**
 * Step two: the model as radio cards (arrows choose), the tone, and the
 * guardrail switches (Space toggles).
 */
export function BehaviourStep({
  model,
  onModel,
  tone,
  onTone,
  guards,
  onGuard,
}: BehaviourStepProps) {
  const name = useId();
  return (
    <div className="flex flex-col gap-4">
      <fieldset className="flex flex-col gap-2">
        <legend className="mb-2 text-xs font-medium text-muted-foreground">
          Model
        </legend>
        <RadioGroup
          aria-label="Model"
          value={model}
          onValueChange={onModel}
          className="@md:grid-cols-3"
        >
          {MODELS.map((item) => {
            const checked = item.id === model;
            return (
              <label
                key={item.id}
                className={cn(
                  "relative isolate flex cursor-pointer flex-col gap-1 rounded-xl border px-3 py-2.5 outline-none has-focus-visible:ring-2 has-focus-visible:ring-ring",
                  checked ? "border-chart-1" : "border-border",
                )}
              >
                <span
                  aria-hidden="true"
                  className={cn(
                    "absolute inset-0 -z-10 rounded-xl",
                    checked ? "bg-chart-1/10" : "hover:bg-muted",
                  )}
                />
                <RadioGroupItem value={item.id} className="sr-only" />
                <span className="flex items-center justify-between text-sm font-medium">
                  {item.name}
                  <span
                    aria-hidden="true"
                    className={cn(
                      "flex size-4 items-center justify-center rounded-full border",
                      checked ? "border-chart-1" : "border-muted-foreground/60",
                    )}
                  >
                    {checked ? (
                      <span className="size-2 rounded-full bg-chart-1" />
                    ) : null}
                  </span>
                </span>
                <span className="text-xs text-muted-foreground">
                  {item.text}
                </span>
              </label>
            );
          })}
        </RadioGroup>
      </fieldset>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="text-xs font-medium text-muted-foreground">Tone</span>
        <SegmentedControl
          aria-label="Tone"
          options={[...TONES]}
          value={tone}
          onValueChange={onTone}
        />
      </div>
      <ul className="flex flex-col gap-1">
        {GUARDRAILS.map((guard) => {
          const id = `${name}-${guard.id}`;
          return (
            <li
              key={guard.id}
              className="flex items-center justify-between gap-3 py-1"
            >
              <label
                htmlFor={id}
                className="flex min-w-0 cursor-pointer items-start gap-2.5"
              >
                <ShieldIcon
                  aria-hidden="true"
                  className="mt-0.5 size-4 shrink-0 text-chart-2"
                />
                <span className="flex min-w-0 flex-col">
                  <span className="text-sm">{guard.label}</span>
                  <span className="text-xs text-muted-foreground">
                    {guard.text}
                  </span>
                </span>
              </label>
              <Switch
                id={id}
                checked={guards.includes(guard.id)}
                onCheckedChange={(on) => onGuard(guard.id, on)}
              />
            </li>
          );
        })}
      </ul>
    </div>
  );
}

