    answer: [
      {
        text: "Dr Okafor and Dr Hassan both work Saturday mornings at Harbour Street.",
        cite: 3,
      },
      { text: "Saturday visits book up about a week ahead.", cite: 2 },
    ],
  },
];

/** The step names, in order. */
export const STEP_NAMES = ["Connect data", "Choose behaviour", "Test it"];

import { CheckIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { InfoIcon, PlugIcon } from "../icons";
import { SOURCES } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for step one, the sources. */
export interface SourceStepProps {
  /** Sync progress of each source by id, or null when it is not connected. */
  progress: Record<string, number | null>;
  onConnect: (id: string) => void;
}

/**
 * Step one: each source with its size and either a synced mark, a progress
 * bar while it syncs, or a Connect button. A note says the assistant only reads.
 */
export function SourceStep({ progress, onConnect }: SourceStepProps) {
  return (
    <div className="flex flex-col gap-3">
      <ul className="flex flex-col gap-1 rounded-xl border border-border py-1">
        {SOURCES.map((source) => {
          const value = progress[source.id] ?? null;
          return (
            <li
              key={source.id}
              className="grid grid-cols-[2rem_1fr_auto] items-center gap-3 px-3 py-2.5"
            >
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-8 items-center justify-center rounded-lg text-xs font-semibold",
                  source.tint,
                )}
              >
                {source.name[0]}
              </span>
              <span className="flex min-w-0 flex-col gap-1">
                <span className="truncate text-sm font-medium">
                  {source.name}
                </span>
                {value !== null && value < 100 ? (
                  <span
                    role="progressbar"
                    aria-label={`${source.name} sync`}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={Math.round(value)}
                    className="h-1.5 w-full max-w-40 overflow-hidden rounded-full bg-muted"
                  >
                    <span
                      className="block h-full w-(--w) rounded-full bg-chart-1"
                      style={
                        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                        { "--w": `${value}%` } as VarStyle
                      }
                    />
                  </span>
                ) : (
                  <span className="text-xs text-muted-foreground">
                    {source.size}
                  </span>
                )}
              </span>
              {value === null ? (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => onConnect(source.id)}
                  aria-label={`Connect ${source.name}`}
                >
                  <PlugIcon aria-hidden="true" className="size-4" />
                  Connect
                </Button>
              ) : value < 100 ? (
                <span className="text-xs text-muted-foreground tabular-nums">
                  Syncing {Math.round(value)}%
                </span>
              ) : (
                <span className="flex items-center gap-1 text-xs text-marketing-green-ink">
                  <CheckIcon aria-hidden="true" className="size-3.5" />
                  Synced
                </span>
              )}
            </li>
          );
        })}
      </ul>
      <p className="flex items-start gap-2 text-xs text-muted-foreground">
        <InfoIcon aria-hidden="true" className="mt-px size-3.5 shrink-0" />
        The assistant only reads these sources. It never books, moves or cancels
        a visit.
      </p>
    </div>
  );
}

