/** Props for the setup stepper. */
export interface StepperProps {
  names: string[];
  step: number;
  onStep: (step: number) => void;
}

/**
 * The three steps as buttons over bars. A finished step's bar is full and
 * its number crossfades to a check. The current step is marked for screen readers.
 */
export function Stepper({ names, step, onStep }: StepperProps) {
  return (
    <ol className="grid grid-cols-3 gap-2">
      {names.map((name, index) => {
        const done = index < step;
        const current = index === step;
        return (
          <li key={name}>
            <Button
              variant="ghost"
              aria-current={current ? "step" : undefined}
              onClick={() => onStep(index)}
              size="sm"
              className="w-full text-left"
            >
              <span className="flex w-full flex-col items-stretch gap-2 px-1.5 py-1.5 font-normal">
                <span
                  aria-hidden="true"
                  className="h-1 overflow-hidden rounded-full bg-muted"
                >
                  <span
                    className={cn(
                      "block h-full rounded-full bg-chart-1 motion-safe:transition-all motion-safe:duration-500 motion-safe:ease-out",
                      done ? "w-full" : current ? "w-1/2" : "w-0",
                    )}
                  />
                </span>
                <span className="flex min-w-0 items-center gap-2">
                  <span
                    aria-hidden="true"
                    className={cn(
                      "relative grid size-5 shrink-0 place-items-center rounded-full text-xs font-semibold motion-safe:transition-colors",
                      done || current
                        ? "bg-chart-1 text-primary-foreground"
                        : "bg-muted text-muted-foreground",
                    )}
                  >
                    <span
                      className={cn(
                        "col-start-1 row-start-1 motion-safe:transition-opacity",
                        done ? "opacity-0" : "opacity-100",
                      )}
                    >
                      {index + 1}
                    </span>
                    <CheckIcon
                      className={cn(
                        "col-start-1 row-start-1 size-3 motion-safe:transition-opacity",
                        done ? "opacity-100" : "opacity-0",
                      )}
                    />
                  </span>
                  <span
                    className={cn(
                      "truncate text-xs",
                      current
                        ? "font-medium text-foreground"
                        : "text-muted-foreground",
                    )}
                  >
                    {name}
                    {done ? <span className="sr-only">, done</span> : null}
                  </span>
                </span>
              </span>
            </Button>
          </li>
        );
      })}
    </ol>
  );
}

"use client";

import { type FormEvent, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { SendIcon } from "../icons";
import { useTicker } from "../lib/use-ticker";
import { countAllWords, revealParts } from "../lib/words";
import { QUESTIONS, SOURCES } from "./data";

const LIMIT = 30;

/**
 * Step three: ask a test question and watch the cited answer stream in. Each
 * sentence ends with the number of the source it came from.
 */
export function TestStep() {
  const [text, setText] = useState(QUESTIONS[0]!.question);
  const [asked, setAsked] = useState<number | null>(null);
  const stream = useTicker(LIMIT, 70);

  const ask = (index: number) => {
    setText(QUESTIONS[index]?.question ?? "");
    setAsked(index);
    stream.start();
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    const match = QUESTIONS.findIndex(
      (item) => item.question.toLowerCase() === text.trim().toLowerCase(),
    );
    ask(match >= 0 ? match : 0);
  };

  const question = asked === null ? null : QUESTIONS[asked];
  const parts = question?.answer.map((sentence) => sentence.text) ?? [];
  const shown = revealParts(parts, stream.tick * 2);
  const streaming = stream.running && stream.tick * 2 < countAllWords(parts);

  return (
    <div className="flex h-full flex-col gap-3">
      <div className="flex flex-wrap gap-1.5">
        {QUESTIONS.map((item, index) => (
          <Button
            key={item.question}
            variant={asked === index ? "secondary" : "outline"}
            size="sm"
            className="h-auto min-h-8 whitespace-normal"
            onClick={() => ask(index)}
          >
            <span className="py-1">{item.question}</span>
          </Button>
        ))}
      </div>
      <div
        aria-live="polite"
        aria-busy={streaming}
        className="scroll-fade-effect-y scrollbar-none min-h-0 flex-1 overflow-y-auto rounded-xl border border-border p-3 text-sm leading-relaxed"
      >
        {question ? (
          <div className="flex gap-2.5">
            {/* A box one text line tall centres the icon on the first line, with no nudge. */}
            <span className="flex h-5 shrink-0 items-center">
              <SparklesIcon
                aria-hidden="true"
                className="size-4 shrink-0 text-chart-4"
              />
            </span>
            <p aria-hidden={streaming}>
              {question.answer.map((sentence, index) => {
                const part = shown[index] ?? "";
                if (!part) return null;
                const source = SOURCES[sentence.cite - 1];
                return (
                  <span key={sentence.text}>
                    {part}
                    {part === sentence.text ? (
                      <sup
                        className={cn(
                          "ml-0.5 rounded px-1 text-xs font-semibold",
                          source?.tint,
                        )}
                      >
                        <span className="sr-only">Source: {source?.name}</span>
                        <span aria-hidden="true">{sentence.cite}</span>
                      </sup>
                    ) : null}{" "}
                  </span>
                );
              })}
            </p>
          </div>
        ) : (
          <p className="text-muted-foreground">
            Ask a question a patient might send. The answer uses only your
            connected sources.
          </p>
        )}
      </div>
      <form onSubmit={submit} className="flex gap-2">
        <Input
          value={text}
          onChange={(event) => setText(event.target.value)}
          aria-label="Test question"
          className="min-w-0 flex-1"
        />
        <Button
          type="submit"
          size="icon"
          className="size-9"
          aria-label="Ask"
          disabled={streaming || !text.trim()}
        >
          <SendIcon aria-hidden="true" />
        </Button>
      </form>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

/** A clock that counts ticks while it runs. Blocks read their simulated progress off the tick. */
export interface Ticker {
  /** Ticks counted since the last start. */
  tick: number;
  running: boolean;
  /** True once the tick has reached the limit. */
  done: boolean;
  /** Starts from zero. With reduced motion it jumps straight to the limit. */
  start: () => void;
  /** Holds the tick where it is. */
  stop: () => void;
  /** Stops and goes back to zero. */
  reset: () => void;
  /** Jumps to the limit at once. */
  finish: () => void;
}

/**
 * Counts one tick every `tickMs` until it reaches `limit`, then stops on its
 * own. The interval is cleared on stop and on unmount, so nothing runs after
 * the block leaves the page. A person who asks for reduced motion gets the
 * finished result in one step.
 */
export function useTicker(limit: number, tickMs = 60): Ticker {
  const reduceMotion = useReducedMotion();
  const [tick, setTick] = useState(0);
  const [running, setRunning] = useState(false);
  const tickRef = useRef(0);

  useEffect(() => {
    if (!running) return;
    const id = window.setInterval(() => {
      tickRef.current = Math.min(limit, tickRef.current + 1);
      setTick(tickRef.current);
      if (tickRef.current >= limit) setRunning(false);
    }, tickMs);
    return () => window.clearInterval(id);
  }, [running, limit, tickMs]);

  const finish = useCallback(() => {
    tickRef.current = limit;
    setTick(limit);
    setRunning(false);
  }, [limit]);

  const start = useCallback(() => {
    if (reduceMotion) {
      finish();
      return;
    }
    tickRef.current = 0;
    setTick(0);
    setRunning(true);
  }, [finish, reduceMotion]);

  const stop = useCallback(() => setRunning(false), []);

  const reset = useCallback(() => {
    tickRef.current = 0;
    setTick(0);
    setRunning(false);
  }, []);

  return { tick, running, done: tick >= limit, start, stop, reset, finish };
}

/** Splits text into words, each with the space after it, so joining them gives the text back. */
export function splitWords(text: string): string[] {
  return text.match(/\S+\s*/g) ?? [];
}

/** The number of words in a text. */
export function countWords(text: string): number {
  return splitWords(text).length;
}

/** The first `count` words of a text, trimmed at the end. A streamed reply shows this as it grows. */
export function takeWords(text: string, count: number): string {
  return splitWords(text).slice(0, Math.max(0, count)).join("").trimEnd();
}

/**
 * Splits a reply made of parts across a running word count: each part gets
 * the words that fall inside it, in order. A part not reached yet gets an
 * empty string, so a block can show its placeholder.
 */
export function revealParts(parts: string[], shown: number): string[] {
  let left = shown;
  return parts.map((part) => {
    const words = countWords(part);
    const take = Math.min(words, Math.max(0, left));
    left -= words;
    return take === words ? part : takeWords(part, take);
  });
}

/** The total number of words across several parts. */
export function countAllWords(parts: string[]): number {
  return parts.reduce((total, part) => total + countWords(part), 0);
}

